INSERT INTO complaints (complaint_id, customer_id, product_id, complaint) VALUES 
(1, 3, 1, 'The football started deflating after just two uses. I expected better quality from this brand.'),
(2, 7, 5, 'The running shoes are very uncomfortable. The cushioning feels hard and hurts my feet.'),
(3, 10, 8, 'The treadmill makes a loud squeaking noise when in use. It’s very distracting while running.'),
(4, 12, 6, 'Compression shorts material is too thin and loses elasticity after a few washes. Not worth it.'),
(5, 15, 2, 'The basketball doesn’t bounce properly. It feels like it loses air too quickly during play.'),
(6, 4, 9, 'The dumbbells have a strong chemical smell and the grip is uncomfortable for longer workouts.'),
(7, 18, 13, 'The camping tent is smaller than advertised. It barely fits two people, let alone three.'),
(8, 9, 16, 'The knee pads feel very flimsy. The padding is too thin to provide proper protection.'),
(9, 1, 10, 'The resistance bands snapped after only two weeks of use. Really poor durability.'),
(10, 5, 3, 'The tennis racket strings broke after a few games. Expected better quality for this price.'),
(11, 20, 7, 'Gym gloves stitching is coming apart after a few workouts. Feels cheaply made.'),
(12, 14, 12, 'The cycling helmet strap is uncomfortable and keeps loosening while riding. Unsafe to use.'),
(13, 6, 4, 'Badminton shuttlecocks are not durable. Feathers come apart after a few rounds of play.'),
(14, 2, 14, 'The climbing rope frays easily. I don’t trust it for safety. Not good for serious climbers.'),
(15, 11, 18, 'The tennis balls lost their bounce after just a few matches. Not worth the price.'),
(16, 19, 22, 'The skateboard deck started cracking after a few weeks. Expected better quality materials.'),
(17, 8, 25, 'Shin guards are too stiff and uncomfortable. Hard to wear for long matches.'),
(18, 16, 29, 'The jump rope handles broke within days. The rope itself feels cheap and flimsy.'),
(19, 17, 27, 'The golf club has a bad grip and feels off-balanced. Not good for professional use.'),
(20, 13, 15, 'Swimming goggles fog up instantly. The anti-fog coating does not work at all.'); 
